-- Create a test agency
INSERT INTO agencies (name, status, business_type, team_size, monthly_budget, created_at, updated_at)
VALUES ('Kyle Realty Group', 'active', 'real_estate', 5, 2000.00, NOW(), NOW());

-- Get the agency ID
SET @agency_id = LAST_INSERT_ID();

-- Create a test client record linked to the agency
INSERT INTO clients (name, email, company, notes, created_by, created_at, updated_at, phone, business_name, business_type, industry, is_active, crm_client_id)
VALUES ('Kyle Thompson', 'kyle@kylerealty.com', 'Kyle Realty Group', 'Test client account for client-side UI testing', 1, NOW(), NOW(), '+1 702-555-0100', 'Kyle Realty Group', 'real_estate', 'Real Estate', 1, @agency_id);

SET @client_id = LAST_INSERT_ID();

-- Update the agency with the client_id reference
UPDATE agencies SET client_id = @client_id WHERE id = @agency_id;

SELECT @agency_id AS agency_id, @client_id AS client_id;

